{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C38"],
      "claim": "In seven patients, tetrabenazine had a mean oral systemic availability of 0.049 ± 0.032, a direct human F measurement well below 20%.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C46"],
      "claim": "Donepezil has an absolute oral bioavailability of 100% in humans, showing that a dimethoxybenzene-containing basic amine without HBD can be completely absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Valbenazine, a tetrabenazine analogue with a modified ketone, has an absolute oral bioavailability of approximately 49% in humans, directly supporting F ≥20% for this structural family.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C62"],
      "claim": "Almorexant, a dimethoxy-tetrahydroisoquinoline amide, had an absolute oral bioavailability of 11.2% in healthy subjects, an example of low F in a related scaffold.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C50"],
      "claim": "Verapamil, a dimethoxyphenyl tertiary amine, had an absolute oral bioavailability of 22.0% in normal subjects, supporting F ≥20% for basic dimethoxyaryl drugs.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "High is better supported. Direct human F values for structurally related dimethoxyaryl/basic-amine drugs are mostly ≥20% (donepezil ~100%, valbenazine ~49%, verapamil ~22-24%), while the low-F tetrabenazine result is less transferable because the query lacks the reducible ketone and has a lactam/side-chain architecture more akin to higher-F analogues. The mixed physicochemical prior does not override this experimental pattern.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the exact query molecule.",
    "All analogues have Morgan similarity below 0.38, so transferability is limited.",
    "The impact of the lactam and 5,6-dimethoxyindane side chain on first-pass metabolism and permeability is unmeasured.",
    "The low neutral fraction at pH 7.4 could lower absorption, but high-F basic amine analogues suggest this is not decisive."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

